          data-subtitle="{{ m.company_title }}{% if m.role_tag %} ｜ {{ m.role_tag }}{% endif %}"
          data-bio="{{ m.bio }}"
          data-links='{{ m.links | tojson }}'
          onclick="openBio(this)">簡介</button>
      </div>
    </div>
    {% endfor %}
  </div>
  {% else %}
  <div class="empty">還沒有導師資料，敬請期待。</div>
  {% endif %}

  <div class="modal-overlay" id="bioModal">
    <div class="modal">
      <h3 id="modalName"></h3>
      <div class="subtitle" id="modalSubtitle"></div>
      <div class="bio" id="modalBio"></div>
      <div class="contact" id="modalContact"></div>
      <button class="close-btn" onclick="closeBio()">關閉</button>
    </div>
  </div>

<script>
function openBio(btn) {
  document.getElementById('modalName').textContent = btn.dataset.name;
  document.getElementById('modalSubtitle').textContent = btn.dataset.subtitle;
  var bioEl = document.getElementById('modalBio');
  bioEl.innerHTML = '';
  btn.dataset.bio.split(/\n\s*\n/).forEach(function(para) {
    if (para.trim()) {
      var p = document.createElement('p');
      p.textContent = para.trim();
      bioEl.appendChild(p);
    }
  });
  var contactEl = document.getElementById('modalContact');
  contactEl.innerHTML = '';
  var links = JSON.parse(btn.dataset.links || '[]');
  links.forEach(function(link) {
    var a = document.createElement('a');
    a.href = link.url;
    a.target = '_blank';
    a.rel = 'noopener';
    a.textContent = link.label;
    contactEl.appendChild(a);
  });
  document.getElementById('bioModal').classList.add('open');
}
function closeBio() {
  document.getElementById('bioModal').classList.remove('open');
}
document.getElementById('bioModal').addEventListener('click', function(e) {
  if (e.target === this) closeBio();
});
</script>
</body>
</html>

