def _client_ip() -> str:
    """站台走Cloudflare Tunnel，真實訪客IP在CF-Connecting-IP，其次才是X-Forwarded-For。"""
    return (
        request.headers.get("CF-Connecting-IP")
        or (request.headers.get("X-Forwarded-For") or "").split(",")[0].strip()
        or request.remote_addr
        or "unknown"
    )


@app.route("/")
def index():
    conn = db.get_conn()
    db.log_visit(conn, _client_ip())
    mentors = [{**dict(m), "links": db.mentor_links(m)} for m in db.list_mentors(conn)]
    total_views = db.get_total_views_since(conn, TRACKING_START)
    conn.close()
    return render_template("index.html", mentors=mentors, total_views=total_views)


